      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-connect-workbuddy\",\n  \"displayName\": \"DSH Connect WorkBuddy\",\n  \"description\": \"把本机登录的 WorkBuddy 模型（国内版与国际版）接入 DeepSeek Harness：每次刷新按上游目录自动读取每个模型的积分倍率，支持逐模型图片输入开关、多账号切换与账号池自动换号，并提供每日签到、卡片与输入框里的胶囊积分读数等只读积分概览。\",\n  \"version\": \"5.12.2\",\n  \"author\": \"dingminhua\",\n  \"copyright\": \"Copyright (c) 2026 LaoDing\",\n  \"license\": \"MIT\",\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"workbuddy\",\n    \"codebuddy\",\n    \"model-provider\",\n    \"credits\"\n  ],\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"bin\": {\n    \"dsh-connect-workbuddy\": \"lib/bin.js\"\n  },\n  \"icon\": \"icons/dsh-connect-workbuddy-128.png\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"3.18.4\"\n  },\n  \"files\": [\n    \"lib\",\n    \"icons\",\n    \"locale\",\n    \"docs/assets\",\n    \"screenshots.json\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"CHANGELOG.md\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"docs/WINDOWS.md\",\n    \"LICENSE\"\n  ],\n  \"scripts\": {\n    \"prepack\": \"npm run build\",\n    \"build\": \"tsdown\",\n    \"test\": \"vitest run\",\n    \"typecheck\": \"tsc -p tsconfig.json && tsc -p tsconfig.client.json\",\n    \"check\": \"pnpm run typecheck && pnpm run test && pnpm run build\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/dingminhua/dsh-connect-workbuddy.git\"\n  },\n  \"homepage\": \"https://github.com/dingminhua/dsh-connect-workbuddy#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/dingminhua/dsh-connect-workbuddy/issues\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.1-rc.1 <5.0.0 || >=4.0.2 <5.0.0\",\n    \"@deepseek-ai/dsh-atomic-write\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-attachment\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-home-paths\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-host-webserver\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-llm\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-llm-pi-ai\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-settings\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/schemastery\": \">=3.18.1-rc.1 <4.0.0 || >=3.18.2 <4.0.0\",\n    \"@earendil-works/pi-ai\": \">=0.85.0 <0.88.0 || >=1.0.0-0 <2.0.0\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@earendil-works/pi-ai\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.1 <5.0.0 || >=4.0.2 <5.0.0\",\n    \"@deepseek-ai/dsh-atomic-write\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-attachment\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-home-paths\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-host-webserver\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-llm\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-llm-pi-ai\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/dsh-settings\": \">=0.1.7-rc.1 <0.3.0-0\",\n    \"@deepseek-ai/schemastery\": \">=3.18.1 <4.0.0 || >=3.18.2 <4.0.0\",\n    \"@earendil-works/pi-ai\": \">=0.85.0 <0.88.0 || >=1.0.0-0 <2.0.0\",\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.31\",\n    \"@types/react-dom\": \"18.3.7\",\n    \"jsdom\": \"^29.1.1\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"18.3.1\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^5.9.3\",\n    \"vitest\": \"^4.1.8\"\n  }\n}\n"
    },
